<?php if($book): ?><div class="card"><div class="card-body"><p class="text-secondary"><?= html_escape($book['author']?:'Pengarang belum diisi'); ?></p><p><strong><?= html_escape($book['library_name']); ?></strong><br><?= html_escape($book['library_address']); ?></p><dl><dt>ISBN</dt><dd><?= html_escape($book['isbn']?:'—'); ?></dd><dt>Penerbit / tahun</dt><dd><?= html_escape(($book['publisher']?:'—').' / '.($book['publish_year']?:'—')); ?></dd><dt>Jenis koleksi</dt><dd><?= $book['format']==='physical'?'Fisik':'Digital'; ?></dd></dl><p><?= nl2br(html_escape($book['description']?:'')); ?></p><?php if($book['format']==='physical'): ?><p><?= (int)$book['available']; ?> eksemplar tersedia. Hubungi perpustakaan pemilik untuk menjadi anggota dan meminjam.</p><?php elseif($book['digital_url']): ?><a class="btn btn-primary" href="<?= html_escape($book['digital_url']); ?>" target="_blank" rel="noopener noreferrer">Buka sumber digital</a><p class="text-secondary small mt-2">Tautan eksternal disediakan perpustakaan pemilik.</p><?php endif; ?></div></div>
<?php else: ?><p class="text-secondary">Koleksi yang dipublikasikan oleh perpustakaan anggota jejaring Rembang. Data pribadi anggota dan transaksi tidak ditampilkan.</p><form method="get" class="row g-2 mb-4"><div class="col-md-5"><input name="q" class="form-control" placeholder="Judul, pengarang, ISBN" value="<?= html_escape($q); ?>"></div><div class="col-md-5"><select name="library_id" class="form-select"><option value="0">Semua perpustakaan</option><?php foreach($libraries as$l): ?><option value="<?= (int)$l['id']; ?>" <?= (int)$l['id']===$library_id?'selected':''; ?>><?= html_escape($l['name']); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Cari</button></div></form><p><?= number_format($total); ?> judul ditemukan</p><div class="row g-3"><?php foreach($rows as$row): ?><div class="col-md-4"><a class="card card-link h-100" href="<?= base_url('jejaring/katalog/'.(int)$row['id']); ?>"><div class="card-body"><span class="badge bg-blue-lt mb-2"><?= $row['format']==='physical'?'Fisik':'Digital'; ?></span><h2 class="h3"><?= html_escape($row['title']); ?></h2><p><?= html_escape($row['author']?:''); ?></p><small><?= html_escape($row['library_name']); ?></small></div></a></div><?php endforeach; ?></div><?php if(!$rows): ?><div class="alert alert-info">Belum ada katalog jejaring yang sesuai. Perpustakaan dapat memublikasikan katalog melalui ruang operasionalnya.</div><?php endif; ?><div class="d-flex gap-2 mt-3"><span>Halaman <?= $page; ?>/<?= $pages; ?></span><?php foreach([$page-1=>'Sebelumnya',$page+1=>'Berikutnya']as$p=>$label):if($p<1||$p>$pages)continue; ?><a class="btn btn-sm" href="<?= base_url('jejaring/katalog?'.http_build_query(['q'=>$q,'library_id'=>$library_id,'page'=>$p])); ?>"><?= $label; ?></a><?php endforeach; ?></div><?php endif; ?></main></body></html>
